u0435 \\u043d\\u0430 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0438 \\u0441\\u043e\\u0431\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0440\\u0435\\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u0445 \\u043a\\u043b\\u0435\\u0442\\u043e\\u043a \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u0430. \\u0421 \\u043f\\u043e\\u043c\\u043e\\u0449\\u044c\\u044e \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0438 \\u043c\\u0438\\u043a\\u0440\\u043e\\u0433\\u0440\\u0430\\u0444\\u0442\\u0438\\u043d\\u0433\\u0430 \\u0430\\u043a\\u0442\\u0438\\u0432\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u00ab\\u0441\\u043f\\u044f\\u0449\\u0438\\u0435\\u00bb \\u0432\\u043e\\u043b\\u043e\\u0441\\u044f\\u043d\\u044b\\u0435 \\u0444\\u043e\\u043b\\u043b\\u0438\\u043a\\u0443\\u043b\\u044b, \\u0443\\u043b\\u0443\\u0447\\u0448\\u0430\\u0435\\u0442\\u0441\\u044f \\u0441\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u0435 \\u043a\\u043e\\u0436\\u0438 \\u0433\\u043e\\u043b\\u043e\\u0432\\u044b \\u0438 \\u0437\\u0430\\u043c\\u0435\\u0434\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441 \\u043f\\u043e\\u0440\\u0435\\u0434\\u0435\\u043d\\u0438\\u044f \\u0432\\u043e\\u043b\\u043e\\u0441. \\u041c\\u0435\\u0442\\u043e\\u0434 \\u043e\\u0441\\u043e\\u0431\\u0435\\u043d\\u043d\\u043e \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u0435\\u043d \\u043d\\u0430 \\u0440\\u0430\\u043d\\u043d\\u0438\\u0445 \\u0441\\u0442\\u0430\\u0434\\u0438\\u044f\\u0445 \\u0430\\u043b\\u043e\\u043f\\u0435\\u0446\\u0438\\u0438 \\u0443 \\u043c\\u0443\\u0436\\u0447\\u0438\\u043d \\u0438 \\u0436\\u0435\\u043d\\u0449\\u0438\\u043d.\\\\r\\\\n\\u041a\\u043b\\u044e\\u0447\\u0435\\u0432\\u044b\\u0435 \\u043f\\u0440\\u0435\\u0438\\u043c\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0430:\\\\r\\\\n\\u041a\\u043b\\u0438\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\