INSERT INTO `ingredients` VALUES (219,1,0,0,NULL,'2025-12-10 13:42:29',NULL,'talk','{\"en\": \"Talc\", \"ru\": \"Тальк\", \"uk\": \"Тальк\"}','0'),(220,1,1,0,NULL,'2025-12-08 14:37:22','{\"en\": \"Цей інтенсивний засіб SOS, розроблений з комплексом QMS NEOTEC A15™, містить потужні інгредієнти, які допомагають відновити та збалансувати стресовану шкіру ...\", \"ru\": \"Цей інтенсивний засіб SOS, розроблений з комплексом QMS NEOTEC A15™, містить потужні інгредієнти, які допомагають відновити та збалансувати стресовану шкіру ...\", \"uk\": \"Цей інтенсивний засіб SOS, розроблений з комплексом QMS NEOTEC A15™, містить потужні інгредієнти, які допомагають відновити та збалансувати стресовану шкіру ...\"}','neotec-a15','{\"en\": \"NEOTEC A15™\", \"ru\": \"NEOTEC A15™\", \"uk\": \"NEOTEC A15™\"}','1'),(221,1,1,0,NULL,'2025-12-10 13:42:29',NULL,'persian-silk-tree','{\"en\": \"Persian Silk Tree Extract\", \"ru\": \"Экстракт персидского шелкового дерева\", \"uk\": \"Екстракт перського шовкового дерева\"}','0'),(222,1,1,0,NULL,'2025-12-10 13:42:29',NULL,'marine-complex','{\"en\": \"Marine Complex\", \"ru\": \"Морской комплекс\", \"uk\": \"Морський комплекс\"}','1'),(223,1,1,0,NULL,'2025-12-10 13:42:29',NULL,'botanical-oils','{\"en\": \"Botanical Oils\", \"ru\": \"Растительные масла\", \"uk\": \"Рослинні олії\"}','0'),(224,1,1,0,NULL,'2025-12-10 13:42:29',NULL,'gamamelis','{\"en\": \"Witch Hazel\", \"ru\": \"Гамамелис\", \"uk\": \"Гамамеліс\"}','0'),(225,1,1,0,NULL,'2025-12-10 13:42:29',NULL,'oliia-nasinnia-kukurudzi-v-pojednanni-z-unikalnoiu-emulguiucoiu-sistemoiu','{\"en\": \"Corn Seed Oil with Emulsifying System\", \"ru\": \"Масло семян кукурузы с уникальной эмульгирующей системой\", \"uk\": \"Олія насіння кукурудзи з унікальною емульгуючою системою\"}','0'),(226,1,1,0,NULL,'2025-12-10 13:42:29',NULL,'alantoyin','{\"en\": \"Allantoin\", \"ru\": \"Алантоин\", \"uk\": \"Алантоїн\"}','0'),(227,1,1,0,NULL,'2025-12-10 13:42:29',NULL,'bufer-molocnoyi-kisloti','{\"en\": \"Lactic Ac