INSERT INTO `products` VALUES (1,2001100,4025614508229,'200 ml',2695,55,NULL,'2025-12-11 13:48:12',1,'{\"en\": \"Gentle Cleansing Milk\", \"ru\": \"Мягкое очищающее молочко\", \"uk\": \"Ніжне очищувальне молочко\"}','nizhne-ochischuvalne-molochko',NULL,'1','{\"uk\": null}','{\"en\": \"Suitable for all skin types, especially recommended for dry skin.\"}','{\"en\": null}','1','2x2'),(2,2088100,4025614508373,'200 ml',2695,55,NULL,'2025-12-11 13:47:58',1,'{\"en\": \"Energizing Cleansing Gel\", \"ru\": \"Заряжающий очищающий гель\", \"uk\": \"Тонізуючий очищувальний гель\"}','tonizuyuchiy-ochischuvalniy-gel','6','5','{\"uk\": null}','{\"en\": \"Cleansing, moisturizing, soothing and regenerating the skin.\", \"ru\": \"Очищение, увлажнение, успокоение и регенерация кожи.\", \"uk\": \"Очищення, зволоження, заспокоєння та регенерація шкіри.\"}','{\"en\": \"<div class=\\\"product-card__main-description-content\\\"><div><strong>Легкий зволожувальний флюїд для пружної та захищеної шкіри</strong></div><div>Відчуйте глибоке зволоження та покращений захист за допомогою рідкого протеїнового флюїду Hydromax — легкого зволожуючого флюїду, спеціально розробленого для зміцнення, захисту та покращення природного бар\'єру вашої шкіри.&nbsp;</div><div><br></div><div><strong>Як це працює:</strong></div><div>Протеїнова рідина Hydromax Liquid створює на поверхні шкіри повітропроникну, але захисну плівку, ефективно утримуючи вологу та посилюючи ефективність раніше нанесених засобів догляду за шкірою. Її унікальний герметичний ефект запобігає втраті вологи, підтримує клітинне дихання та покращує загальний стан і стійкість шкіри.</div><div><br></div><div><br></div><div><strong>Основні переваги:</strong></div><ul><li><strong>Глибоке зволоження:</strong> Забезпечує необхідний рівень зволоження для захисту шкіри від втрати вологи.</li><li><strong>Підтримка бар\'єру:</strong> Значно зміцнює та покращує природну бар\'єрну функцію вашої шкіри.</li><li><strong>Підвищена еластичність:</strong> Сприяє пружності та еластичності шкіри, одночасно підвищуючи її еластичність.</li><li><strong>Покращений клітинний метаболізм:</strong> активує та покращує метаболізм клітин шкіри для помітно здоровішої шкіри.</li><li><strong>Еластична та м\'яка:</strong> робить шкіру гладкою, м\'якою та еластичною.</li><li><strong>Ідеально підходить для теплої погоди:</strong> легка, нежирна текстура робить його ідеальним для літа та теплішого клімату.</li></ul><div><br></div>\\n                    </div>\", \"uk\": null}','1','2x1'),(3,2002100,4025614508236,'200 ml',2695,55,NULL,'2025-12-11 13:48:12',1,'{\"en\": \"Hydrating Toner\", \"ru\": \"Увлажняющий тонер\", \"uk\": \"Зволожувальний тонік\"}','zvolozhuvalniy-tonik',NULL,'2','{\"uk\": null}','{\"uk\": null}','{\"uk\": null}','1',NULL),(4,2158100,4025614515401,'200ml',2695,55,NULL,'2025-12-11 13:48:08',1,'{\"en\": \"Calming Toner\", \"ru\": \"Успокаивающий тонер\", \"uk\": \"Заспокійливий тонік\"}','zaspokiyliviy-tonik',NULL,'3','{\"uk\": null}','{\"uk\": null}','{\"uk\": null}','1',NULL),(5,2010100,4025614508182,'30 ml',4802,98,NULL,'2025-12-11 13:47:58',2,'{\"en\": \"7% AHA Active Exfoliant Resurfacing Liquid\", \"ru\": \"Активный отшелушивающий раствор 7% AHA\", \"uk\": \"Активний відлущувальний розчин 7% AHA\"}','aktivnii-vidlushhuvalnii-rozcin-7-aha',NULL,'4','{\"uk\": null}','{\"uk\": null}','{\"uk\": null}','1',NULL),(6,2006100,4025614508175,'30 ml',4802,98,NULL,'2025-12-11 13:47:58',2,'{\"en\": \"10% AHA Active Exfoliant Resurfacing Liquid\", \"ru\": \"Активный отшелушивающий раствор 10% AHA\", \"uk\": \"Активний відлущувальний розчин 10% AHA\"}','aktivnii-vidlushhuvalnii-rozcin-10-aha',NULL,'6','{\"uk\": null}','{\"uk\": null}','{\"uk\": null}','1',NULL),(7,2115100,4025614508533,'200 ml',4802,98,NULL,'2025-12-11 13:47:58',2,'{\"en\": \"Gentle Exfoliating Daily Lotion\", \"ru\": \"Мягкий отшелушивающий ежедневный лосьон\", \"uk\": \"Ніжний відлущувальний щоденний лосьйон\"}','nizhniy-vidluschuvalniy-schodenniy-losyon',NULL,'7',